-- 02-teams: 10 records from the uploaded workbook, not live Sheets.
-- DB Browser: save pending edits first. Execute this WHOLE file, then Write Changes.
-- SAVEPOINT supports DB Browser's existing transaction; there is no BEGIN/COMMIT.
-- Identical reruns do nothing. Conflicts roll back the transaction instead of overwriting.
PRAGMA foreign_keys=ON;
SAVEPOINT afl_import_2;
CREATE TEMP TABLE afl_import_2 AS SELECT id, league_id, legacy_team_id, retired_at FROM teams WHERE 0;
CREATE TEMP TABLE afl_import_2_guard(ok INTEGER);
CREATE TEMP TRIGGER afl_import_2_check BEFORE INSERT ON afl_import_2_guard
BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM leagues WHERE id='36c6e53f-7be2-5a94-84a8-0df871aae9fd' AND name='AFL') THEN RAISE(ROLLBACK,'Missing expected AFL league record.') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM afl_import_2 i JOIN teams t ON t.id=i.id WHERE t.league_id IS NOT i.league_id OR t.legacy_team_id IS NOT i.legacy_team_id OR t.retired_at IS NOT i.retired_at) THEN RAISE(ROLLBACK,'Existing ID has different data; no records overwritten.') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM afl_import_2 i JOIN teams t ON t.league_id=i.league_id AND t.legacy_team_id=i.legacy_team_id WHERE t.id<>i.id) THEN RAISE(ROLLBACK,'An existing natural key uses another ID; reconcile before importing.') END;
END;
DROP TRIGGER afl_import_2_check;
DROP TABLE afl_import_2_guard;
DROP TABLE afl_import_2;
RELEASE SAVEPOINT afl_import_2;
PRAGMA foreign_key_check;
SELECT 'teams' AS imported_table, COUNT(*) AS reviewed_records_present FROM teams WHERE id IN ('90da7069-5188-575b-b2b2-91babe77e14e', '38214cb1-42e3-5517-9fd9-a45b97fc962c', '02718a56-e7d2-553c-8cd5-441026f30ca5', 'e63aa8e6-f9e4-597c-bbc9-a031a0bf79b4', 'fd78f6ed-7a0d-5955-90db-dc27c3f3a9ab', 'f0abea88-d59e-5e39-8982-9af51677cc2c', 'c18daf46-b76a-510f-88b5-5084d325b24d', '9fcb903b-26ca-584d-9911-161ef1c9dcc2', '3165d4af-822f-5d44-a7d6-d9e0ac1e17c7', '57e4291e-9ed9-52e3-b954-734860260698');
